import { reactive } from 'vue';
import { LOW_CONFIDENCE } from 'src/constants';
import type { dynamicObj } from 'src/pages/assets';
import displayFieldLabel from 'src/utils/displayFieldLabel';

/**
 * CORE-6161: the fields that keep a document from validating, worked out from
 * what the validation screen already holds — the form models and the record,
 * including the codes the backend stamped on the fields at the last save.
 *
 * Read-only on purpose: the real local pass (`validateDocumentFields`) clears
 * a value the text validator rejects, so it must never run just to fill the
 * assistant. The text-format result is picked up from `input_error` instead.
 */

export const OPEN_VALIDATION_ASSISTANT_EVENT = 'validation_assistant_open';
export const TOGGLE_VALIDATION_ASSISTANT_EVENT = 'validation_assistant_toggle';
export const FOCUS_BLOCKED_FIELD_EVENT = 'validation_assistant_focus_field';
export const FOCUS_BLOCKED_TABLE_EVENT = 'validation_assistant_focus_table';

/** Set by the validation screen, which hosts the panel. */
export const validationAssistantHost = reactive({ mounted: false, open: false });

export type BlockerKind =
  | 'required'
  | 'format'
  | 'amount'
  | 'confirm'
  | 'rule'
  | 'at_least_one';

export interface FieldBlocker {
  field_name: string;
  label: string;
  section: string;
  kind: BlockerKind;
  reason: string;
}

export interface TableBlocker {
  table_name: string;
  row_index: number | null;
  column: string;
  reason: string;
}

export interface ValidationBlockers {
  /** Fields the user can see and fix, in form order. */
  blocking: FieldBlocker[];
  /** Fields that block but are hidden from this user or have no access. */
  hidden: FieldBlocker[];
  tables: TableBlocker[];
  total: number;
}

export interface BuildBlockersInput {
  record: dynamicObj | null | undefined;
  formLayout: dynamicObj[] | null | undefined;
  formBuilderModel: dynamicObj | null | undefined;
  formBuilderConfigModel: dynamicObj | null | undefined;
  t: (key: string, params?: dynamicObj) => string;
  canViewField?: (fieldId: string) => boolean;
}

const labelResolver = { ...displayFieldLabel.methods } as dynamicObj;

// Not shown as an error on the form (setFieldErrors skips them); an amount
// mismatch only counts once the form shows it (input_error), like the form does.
const NON_BLOCKING_CODES = new Set([...LOW_CONFIDENCE, 'AMOUNTS_MISMATCH']);

interface LayoutField {
  name: string;
  id: string;
  hidden: boolean;
  section: string;
}

function collectLayoutFields(
  rows: dynamicObj[],
  section: string,
  out: LayoutField[],
) {
  for (const element of rows || []) {
    if (Array.isArray(element?.rows)) {
      collectLayoutFields(element.rows, section, out);
      continue;
    }
    if (!element?.name) {
      continue;
    }
    out.push({
      name: element.name,
      id: element.id,
      hidden: !!element.is_hidden,
      section,
    });
  }
}

function layoutFields(formLayout: dynamicObj[]): LayoutField[] {
  const out: LayoutField[] = [];
  for (const group of formLayout) {
    const section = group?.title ? labelResolver.getFieldLabel(group, '') : '';
    collectLayoutFields(group?.rows || [], section, out);
  }
  return out;
}

// Codes from FieldErrorCodes (DocBits_API constants/error_codes.py).
const CODE_KINDS: Record<string, BlockerKind> = {
  REQUIRED: 'required',
  REQUIRED_CONDITIONAL: 'required',
  FORCED_VALIDATION: 'confirm',
  INVALID_VALUE: 'format',
  FORMAT_MISMATCH: 'format',
  REQUIRED_PATTERN_NOT_MATCHED: 'format',
  DATE_INVALID: 'format',
  OUT_OF_RANGE: 'format',
  VALUE_NOT_ALLOWED: 'format',
  AMOUNTS_MISMATCH: 'amount',
  AMOUNTS_PAIR_MISMATCH: 'amount',
  AMOUNTS_PAIR1_MISMATCH: 'amount',
  AMOUNTS_PAIR2_MISMATCH: 'amount',
  AMOUNTS_PAIR3_MISMATCH: 'amount',
  DISCOUNT_AND_DISCOUNT_PERCENTAGE_MISMATCH: 'amount',
  LINE_AMOUNTS_MISMATCH: 'amount',
  LINES_HEADER_MISMATCH: 'amount',
};

function kindForCode(code: string): BlockerKind {
  return CODE_KINDS[code] ?? 'rule';
}

function atLeastOneFields(
  record: dynamicObj,
  formBuilderModel: dynamicObj,
): Set<string> {
  const unmet = new Set<string>();
  const pairs = record?.required_field_pairs;
  if (!Array.isArray(pairs)) {
    return unmet;
  }
  for (const fields of pairs) {
    if (!Array.isArray(fields)) {
      continue;
    }
    const filled = fields.some(
      (name: string) => !!formBuilderModel[name]?.formatted_value,
    );
    if (!filled) {
      fields.forEach((name: string) => unmet.add(name));
    }
  }
  return unmet;
}

function tableBlockers(
  record: dynamicObj,
  t: BuildBlockersInput['t'],
): TableBlocker[] {
  const out: TableBlocker[] = [];
  const tables = Array.isArray(record?.tables) ? record.tables : [];
  for (const table of tables) {
    const messages = Array.isArray(table?.messages) ? table.messages : [];
    for (const message of messages) {
      if (!message?.message || message.message_code === 'COLUMN_NOT_MAPPED') {
        continue;
      }
      const row_index =
        typeof message.row_index === 'number' ? message.row_index : null;
      out.push({
        table_name: table.name || '',
        row_index,
        column: message.col_name ? t(message.col_name) : '',
        reason: message.message_code
          ? t(String(message.message_code).toLowerCase())
          : message.message,
      });
    }
  }
  return out;
}

export function buildValidationBlockers(
  input: BuildBlockersInput,
): ValidationBlockers {
  const { record, formLayout, formBuilderModel, formBuilderConfigModel, t } =
    input;
  const canViewField = input.canViewField ?? (() => true);
  const empty: ValidationBlockers = {
    blocking: [],
    hidden: [],
    tables: [],
    total: 0,
  };
  if (!record || !Array.isArray(formLayout) || !formBuilderModel) {
    return empty;
  }

  const configModel = formBuilderConfigModel || {};
  const unmetAtLeastOne = atLeastOneFields(record, formBuilderModel);
  const blocking: FieldBlocker[] = [];
  const hidden: FieldBlocker[] = [];
  const seen = new Set<string>();

  for (const field of layoutFields(formLayout)) {
    const model = formBuilderModel[field.name];
    const config = configModel[field.name];
    if (!model || !config || seen.has(field.name)) {
      continue;
    }
    seen.add(field.name);

    const value_empty = !model.formatted_value;
    const code: string = model.validation_code || '';
    let kind: BlockerKind | null = null;
    let reason = '';

    if (config.is_required && value_empty) {
      kind = 'required';
      reason = t('validation_assistant_reason_required');
    } else if (unmetAtLeastOne.has(field.name)) {
      kind = 'at_least_one';
      reason = model.input_error || t('validation_assistant_reason_at_least_one');
    } else if (
      !model.is_valid &&
      code &&
      !NON_BLOCKING_CODES.has(code) &&
      !(code === 'REQUIRED' && !value_empty)
    ) {
      kind = kindForCode(code);
      reason = model.validation_message || t(code);
    } else if (model.input_error) {
      kind = code ? kindForCode(code) : 'format';
      reason = model.input_error;
    }

    if (!kind) {
      continue;
    }

    const blocker: FieldBlocker = {
      field_name: field.name,
      label: labelResolver.getFieldLabel(config, '') || field.name,
      section: field.section,
      kind,
      reason,
    };

    const hiddenForUser =
      field.hidden || !!config.is_hidden || !canViewField(field.id);
    (hiddenForUser ? hidden : blocking).push(blocker);
  }

  const tables = tableBlockers(record, t);
  return {
    blocking,
    hidden,
    tables,
    total: blocking.length + hidden.length + tables.length,
  };
}
